import React from 'react';
import './StarRating.css';

const StarRating = ({ score, onChange }) => {
    return (
        <div className="star-rating">
            {[1, 2, 3, 4].map(star => (
                <span
                    key={star}
                    className={star <= score ? 'star filled' : 'star'}
                    onClick={() => onChange(star)}
                >
                    &#9733;
                </span>
            ))}
        </div>
    );
};

export default StarRating;
